def diagonal_sum_total(grid):
    n = len(grid)
    total = 0
    for i in range(n):
        total += grid[i][i]
        j = n - 1 - i
        if j != i:
            total += grid[i][j]
    return total

def is_magic_square(grid):
    n = len(grid)
    if n == 0:
        return True
    target = sum(grid[0])
    for row in grid:
        if sum(row) != target:
            return False
    for c in range(n):
        if sum(grid[r][c] for r in range(n)) != target:
            return False
    if sum(grid[i][i] for i in range(n)) != target:
        return False
    if sum(grid[i][n - 1 - i] for i in range(n)) != target:
        return False
    return True

def count_paths(grid):
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return 0
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = 1
    for i in range(rows):
        for j in range(cols):
            if i == 0 and j == 0:
                continue
            if grid[i][j] == 1:
                dp[i][j] = 0
                continue
            top = dp[i - 1][j] if i > 0 else 0
            left = dp[i][j - 1] if j > 0 else 0
            dp[i][j] = top + left
    return dp[rows - 1][cols - 1]

def count_islands(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not seen[i][j]:
                count += 1
                stack = [(i, j)]
                seen[i][j] = True
                while stack:
                    x, y = stack.pop()
                    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 1 and not seen[nx][ny]:
                            seen[nx][ny] = True
                            stack.append((nx, ny))
    return count

def flood_fill(grid, sr, sc, new_value):
    rows, cols = len(grid), len(grid[0])
    old_value = grid[sr][sc]
    result = [row[:] for row in grid]
    if old_value == new_value:
        return result
    stack = [(sr, sc)]
    result[sr][sc] = new_value
    while stack:
        x, y = stack.pop()
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and result[nx][ny] == old_value:
                result[nx][ny] = new_value
                stack.append((nx, ny))
    return result

def distinct_value_count(grid):
    s = set()
    for row in grid:
        for v in row:
            s.add(v)
    return len(s)

def is_point_symmetric(grid):
    rotated = [row[::-1] for row in grid[::-1]]
    return rotated == grid

def border_sum(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    total = 0
    for i in range(rows):
        for j in range(cols):
            if i == 0 or i == rows - 1 or j == 0 or j == cols - 1:
                total += grid[i][j]
    return total

def count_palindrome_columns(grid):
    if not grid or not grid[0]:
        return 0
    cols = len(grid[0])
    rows = len(grid)
    count = 0
    for c in range(cols):
        col = [grid[r][c] for r in range(rows)]
        if col == col[::-1]:
            count += 1
    return count

def multiply_matrices(a, b):
    m = len(a)
    n = len(b)
    p = len(b[0]) if n > 0 else 0
    result = [[0] * p for _ in range(m)]
    for i in range(m):
        for j in range(p):
            s = 0
            for k in range(n):
                s += a[i][k] * b[k][j]
            result[i][j] = s
    return result

def find_value_position(grid, target):
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v == target:
                return (i, j)
    return None

def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True
    rows, cols = len(grid), len(grid[0])
    even_val = grid[0][0]
    odd_val = None
    for i in range(rows):
        for j in range(cols):
            if (i + j) % 2 == 0:
                if grid[i][j] != even_val:
                    return False
            else:
                if odd_val is None:
                    odd_val = grid[i][j]
                elif grid[i][j] != odd_val:
                    return False
    if odd_val is not None and odd_val == even_val:
        return False
    return True

def shift_rows_down(grid, k):
    n = len(grid)
    if n == 0:
        return []
    k = k % n
    if k == 0:
        return [row[:] for row in grid]
    return grid[-k:] + grid[:-k]
